     1	/**
     2	 * Harness adapter interface.
     3	 *
     4	 * Abstracts runtime concerns that vary between agent harnesses (Pi, Claude,
     5	 * local CLI, test) so the dev-loop dispatch and handoff path stays harness-agnostic.
     6	 *
     7	 * This slice is intentionally minimal. Add methods only when the dispatch/handoff
     8	 * path needs them; do not turn the adapter into a generic process wrapper.
     9	 *
    10	 * @typedef {Object} HarnessAdapter
    11	 * @property {() => string} getCwd - Current working directory for the active session.
    12	 * @property {() => NodeJS.ProcessEnv} getEnv - Active environment variables.
    13	 * @property {() => boolean} isInteractive - Whether the session is interactive (vs batch/automated).
    14	 * @property {() => boolean} isInsidePi - Whether the session is running inside the Pi agent harness.
    15	 * @property {() => string} getRepoRoot - Best-effort repository root; falls back to cwd.
    16	 */
    17	
    18	const REQUIRED_METHODS = ["getCwd", "getEnv", "isInteractive", "isInsidePi", "getRepoRoot"];
    19	
    20	/**
    21	 * Validate and freeze a harness-adapter implementation.
    22	 *
    23	 * @param {Partial<HarnessAdapter>} impl
    24	 * @returns {HarnessAdapter}
    25	 */
    26	export function createHarnessAdapter(impl) {
    27	  if (!impl || typeof impl !== "object") {
    28	    throw new TypeError("createHarnessAdapter: impl must be an object");
    29	  }
    30	
    31	  for (const method of REQUIRED_METHODS) {
    32	    if (typeof impl[method] !== "function") {
    33	      throw new TypeError(`createHarnessAdapter: missing required method "${method}"`);
    34	    }
    35	  }
    36	
    37	  return Object.freeze({
    38	    getCwd: impl.getCwd,
    39	    getEnv: impl.getEnv,
    40	    isInteractive: impl.isInteractive,
    41	    isInsidePi: impl.isInsidePi,
    42	    getRepoRoot: impl.getRepoRoot,
    43	  });
    44	}
    45	
    46	/**
    47	 * Type guard for adapter values.
    48	 *
    49	 * @param {*} value
    50	 * @returns {value is HarnessAdapter}
    51	 */
    52	export function isHarnessAdapter(value) {
    53	  if (!value || typeof value !== "object") {
    54	    return false;
    55	  }
    56	  return REQUIRED_METHODS.every((method) => typeof value[method] === "function");
    57	}

