   129	  if (positional[0] === '--file') {
   130	    const file = positional[1];
   131	    // Reject any leading `-`: the path is forwarded to `resolve-dev-loop-startup
   132	    // --spike <path>`, so a value like `-x` could be read as an option (option
   133	    // injection). Fail closed. The free-text question path below is unaffected.
   134	    if (typeof file !== 'string' || file.length === 0 || file.startsWith('-') || positional.length !== 2) {
   135	      return invalidCommand('`start-spike --file` requires exactly one `<path>`.', 'start-spike', tokens);
   136	    }
   137	    return {
   138	      kind: 'start_spike',
   139	      mode: 'file',
   140	      file,
   141	      question: null,
   142	      intent: `start a dev-loop spike from ${file}`,
   143	      tokens,
   144	    };
   145	  }

